({__plugin:null,__load(){if(this.__plugin)return this.__plugin;this.__plugin=function(){"use strict";let locales=unbound.i18n.createLocales({FRIEND_INVITES_DESC:"Manage your friend invite links",CREATE_DESC:"Create a friend invite link",VIEW_DESC:"List your active friend invites",REVOKE_DESC:"Revoke every friend invite you made"});function expiry(invite){var at=invite.expires_at?Date.parse(invite.expires_at):0/0;return Number.isFinite(at)?`<t:${Math.round(at/1e3)}:R>`:"never"}function describeCreated(invite){return`discord.gg/${invite.code} \xb7 Expires: ${expiry(invite)} \xb7 Max uses: \`${invite.max_uses??"∞"}\``}function describeList(invites){return invites.length?invites.map(invite=>`discord.gg/${invite.code} \xb7 Expires: ${expiry(invite)} \xb7 Used: \`${invite.uses??0}/${invite.max_uses??"∞"}\``).join("\n"):"You have no active friend invites."}function isInviteActions(module){return"function"==typeof module?.createFriendInvite}function registerFriendInvites(){var Invites=unbound.metro.findByProps("createFriendInvite","getAllFriendInvites");isInviteActions(Invites)?unbound.commands.register({"friend-invites":{description:"FRIEND_INVITES_DESC",subcommands:{create:{description:"CREATE_DESC",execute:async()=>({ephemeral:!0,content:describeCreated(await Invites.createFriendInvite())})},view:{description:"VIEW_DESC",execute:async()=>({ephemeral:!0,content:describeList(await Invites.getAllFriendInvites())})},revoke:{description:"REVOKE_DESC",execute:async()=>(await Invites.revokeFriendInvites(),{ephemeral:!0,content:"All friend invites were revoked."})}}}}):logger.warn("Friend invites skipped: Discord moved its invite actions.")}return locales.messages,locales.format,locales.useMessages,{start:function start(){registerFriendInvites()}}}();return this.__plugin;}})